import numpy as np
from scipy import optimize, special


def eb_beta_binomial(k, n):
    k, n = np.asarray(k, dtype=float), np.asarray(n, dtype=float)

    def nll(t):
        a, b = np.exp(t)
        return -np.sum(special.betaln(k + a, n - k + b) - special.betaln(a, b))
    r = optimize.minimize(nll, [0.0, 0.0], method='Nelder-Mead',
                          options={'xatol': 1e-10, 'fatol': 1e-12, 'maxiter': 20000})
    a, b = np.exp(r.x)
    return float(a), float(b)


def shrink_alphas(a_hat, se):
    a_hat, se = np.asarray(a_hat, dtype=float), np.asarray(se, dtype=float)

    def nll(t):
        v = se ** 2 + np.exp(2 * t[1])
        return 0.5 * np.sum(np.log(v) + (a_hat - t[0]) ** 2 / v)
    r = optimize.minimize(nll, [a_hat.mean(), 0.0], method='Nelder-Mead',
                          options={'xatol': 1e-10, 'fatol': 1e-12, 'maxiter': 20000})
    mu, tau = r.x[0], np.exp(r.x[1])
    B = se ** 2 / (se ** 2 + tau ** 2)
    return float(mu), float(tau), mu + (1 - B) * (a_hat - mu)
